mapper.select:
SELECT helper_id, member_id, helper_member_id, remark, deleted_flag, create_time, update_time
FROM t_helper
WHERE helper_id = #{helperId}
  AND deleted_flag = #{deletedFlag}

SELECT helper_id, member_id, helper_member_id, remark, deleted_flag, create_time, update_time
FROM t_helper
WHERE member_id = #{memberId}
  AND helper_member_id = #{helperMemberId}
  AND deleted_flag = #{deletedFlag}
LIMIT 1

SELECT helper_member_id
FROM t_helper
WHERE member_id = #{memberId}
  AND deleted_flag = #{deletedFlag}

SELECT COUNT(1)
FROM t_helper
WHERE member_id = #{memberId}
  AND deleted_flag = #{deletedFlag}

mapper.insert:
INSERT INTO t_helper (member_id, helper_member_id, remark, deleted_flag, create_time, update_time)
VALUES (#{memberId}, #{helperMemberId}, NULL, 0, #{now}, #{now})
ON DUPLICATE KEY UPDATE deleted_flag = 0, update_time = #{now}
